import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 110 · Christmas tips: window decorations seen from the street

sc("""Sweetheart, when I was a little girl, the best part of Christmas wasn't the presents. It was walking home from church on Christmas Eve, down Elm Street in the snow, looking into everybody's windows. Every window was a little picture. A candle here, paper snowflakes there, a tiny village in the next one. Today, most windows on most streets are just dark. And it's so easy, and so cheap, to fix.""",
   "snowy street with glowing Christmas windows", "EVERY WINDOW A PICTURE")
sc("""So tonight I'm giving you nine Christmas window ideas that look magical from the street, for under ten dollars, and the three mistakes that make windows look cluttered and cheap. And stay with me, because number nine is the window my mother made every year, and people used to slow their cars down on Elm Street just to look at it.""",
   "car slowing on snowy street at night", "THEY SLOWED THEIR CARS")

ch("Why windows")
sc("""Here's what nobody tells you, honey. Your window is the only decoration that two audiences see. The family inside sees it all day. And every neighbor, every mailman, every lonely person walking a dog at night sees it from the street. In my mother's day, a decorated window was a little gift to the whole neighborhood. You were saying, there's warmth in here. Merry Christmas, whoever you are.""",
   "person walking dog past lit window at night", "A GIFT TO THE STREET")
sc("""And windows are cheap, sweetheart, because the dark does half the work for you. One candle in a window at night looks more magical than a thousand dollars of decorations on a lawn in daylight. In a minute I'll tell you the biggest mistake people make with that candle, because I see it on almost every street.""",
   "single candle glowing in dark window", "THE DARK HELPS")

sc("""Before you start, honey, go outside tonight after dark and stand across the street from your own house. Look at it the way a stranger would. Which windows can you actually see? Which ones are hidden by bushes or a porch roof? That's where you put your effort. My mother did this every year on the first of December, in her coat and slippers, and the neighbors thought she'd lost her mind.""",
   "woman in coat looking at her house at night", "STAND ACROSS THE STREET")
ch("One to three")
sc("""Number one, a single candle in every window. This is the oldest American window tradition there is, honey. The old story goes that a candle in the window meant travelers were welcome, and that the family was waiting for someone to come home. Today, use the battery candles with a timer, so they come on at dusk and go off at bedtime. One in every window, on every floor, facing the street. Simple, and it's stunning.""",
   "colonial house with candle in every window", "A CANDLE IN EVERY WINDOW")
sc("""Number two, paper snowflakes. A stack of plain white printer paper, a pair of scissors, and an evening with your grandchildren. Fold the paper into a triangle, then in half again, then again, cut little shapes along the edges, and unfold. Every one is different, just like real ones. Tape them to the glass with a dot of tape on the back. From the street at night, with the lamp on behind them, they glow.""",
   "child unfolding paper snowflake", "EVERY ONE IS DIFFERENT")
sc("""Number three, a wreath hung inside the window, on a long red ribbon. Most people put the wreath on the door, where nobody sees it after dark. Hang one inside the front window, centered, from a ribbon tied to the curtain rod. With a lamp behind it, the wreath turns into a dark circle with light pouring through it. My mother made hers from the same pine branches she cut for her centerpieces.""",
   "wreath hanging in window on red ribbon", "INSIDE, NOT ON THE DOOR")

ch("Four to six")
sc("""If Grandma's tips are helping you, tap the like button for me, sweetheart. It helps more people find these videos. Number four, glass ornaments on fishing line. Take a few old glass balls, tie each one to a length of clear fishing line, and hang them from the top of the window frame at different heights. From the street, they look like they're floating in the air. Use odd numbers, five or seven, and mix the sizes.""",
   "glass ornaments hanging in window on fishing line", "FLOATING ORNAMENTS")
sc("""Number five, the frosted window. In the nineteen fifties, everybody used a product called Glass Wax, with little cardboard stencils of stars and bells and snowmen. You dabbed it on with a sponge, and it dried white, like frost. Today, honey, you can do the same thing with the canned spray snow from the dollar store and a paper stencil you cut yourself. Just do the bottom corners. A little goes a long way.""",
   "frosted stencil snowflakes on window corner", "1950s FROSTED GLASS")
sc("""Number six, a silhouette. Cut a simple shape out of black construction paper, a nativity, a sleigh and reindeer, a row of carolers, a church with a steeple, and tape it to the glass, facing out. During the day, you barely notice it. At night, with a lamp on behind it, it's a perfect black shadow on a glowing window. People will stop on the sidewalk, honey. In a minute I'll tell you which shape is easiest.""",
   "black paper nativity silhouette in lit window", "A SHADOW PICTURE")

ch("Seven and eight")
sc("""The easiest silhouette, sweetheart, is a row of evergreen trees, in three sizes, standing along the bottom of the window. Just triangles, with a little trunk. Anybody can cut a triangle. And if you're braver, put a little star above the tallest one, cut out of yellow tissue paper, so the light comes through it gold. Danny and I made ours every year, and his trees always leaned to the left.""",
   "black paper tree silhouettes bottom of window", "JUST TRIANGLES")
sc("""Number seven, a window box of evergreens. If you have a window box outside, don't leave it empty and brown all winter. Stick in some cut pine and cedar branches, a few red twigs or holly, and three pinecones. Push them right into the frozen dirt. They'll stay green until spring in the cold. And if you add a little string of battery lights tucked into the branches, it glows from the outside too.""",
   "window box filled with evergreens and pinecones", "NEVER LEAVE IT EMPTY")
sc("""Number eight, a tiny village on the sill. A few little ceramic houses, a church, some bottle-brush trees, a scoop of cotton for snow, and a string of fairy lights tucked behind. Thrift stores are full of those little houses in November, a dollar apiece. Put the village right on the windowsill, facing out, so the street sees the fronts of the houses, not the backs. Most people get that backwards.""",
   "miniature Christmas village on windowsill", "FACE IT OUTWARD")

sc("""A bonus one, sweetheart, for the kitchen window. Dry a few thin slices of orange in a low oven, two hundred degrees for about three hours, until they're like stained glass. Tie them on red thread and hang them in a row across the window. When the sun comes through in the morning, they glow orange and gold, and the kitchen smells like Christmas. Cost of three oranges. My mother called them sun ornaments.""",
   "dried orange slices hanging in sunny kitchen window", "SUN ORNAMENTS")
ch("Three mistakes")
sc("""So far, candles, snowflakes, a wreath, floating ornaments, frost, silhouettes, a window box, and a tiny village. Now, the three mistakes. Mistake one is the candle in the wrong place. People put the window candle off to one side, on a table. From the street, it looks like an accident. Put it dead center on the sill, right in the middle of the glass. Centered looks intentional. Off to the side looks forgotten.""",
   "candle centered on windowsill from outside", "DEAD CENTER")
sc("""Mistake two is too much. People tape up snowflakes and silhouettes and stickers and lights and garland all in the same window, and from the street it's just a mess. One idea per window, honey. Snowflakes in the kitchen. Silhouette in the living room. Candles upstairs. Let each window tell one story. Mistake three is cords. A white extension cord snaking across the sill ruins everything. Use battery lights, or tuck the cord down behind the curtain.""",
   "cluttered window full of decorations", "ONE IDEA PER WINDOW")

ch("Number nine")
sc("""Stay with me, because here's number nine, my mother's window. Every Christmas, she took the big front window on Elm Street, and she pulled the curtains wide open, all the way. She set our Christmas tree right in front of it, close to the glass. She turned off every other lamp in the room. And she lit only the tree. Just the tree, honey, glowing in a dark room, framed in that big window like a painting.""",
   "lit Christmas tree in front window dark room", "JUST THE TREE")
sc("""And on the sill, in front of the tree, she set one candle, dead center, and our family's old wooden nativity, facing out. That was it. No snowflakes, no stickers, no garland. People slowed their cars on Elm Street, sweetheart. Children pressed their mittens against the glass. And my mother used to stand in the dark kitchen doorway, where they couldn't see her, and watch them watching.""",
   "children with mittens looking into lit window", "WATCHING THEM WATCH")
sc("""She told me once, Ruthie, people decorate for the family inside. But a window is for the strangers. Somebody walking by tonight is lonely, or grieving, or a long way from home. And for one minute, standing on that sidewalk, they'll feel like they're part of a family. That's the whole reason for a Christmas window. I've done it every year of my life since.""",
   "lonely person on snowy sidewalk smiling at window", "A WINDOW IS FOR STRANGERS")

ch("Grandma's lesson")
sc("""Light up one window this week, sweetheart, just one, and leave the curtains open. Tell me in the comments, what was in your grandmother's window at Christmas? There are more of my Christmas tips in the playlist right there on your screen. Good night, honey. Merry Christmas.""",
   "row of houses with glowing Christmas windows", "LIGHT ONE WINDOW")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma110", "9 Christmas Window Ideas That Look MAGICAL From the Street (Under $10)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Candles in windows are a long-standing American and Irish Christmas tradition of welcome.",
      "Glass Wax, a window cleaner sold with Christmas stencils, was a popular 1950s holiday window decoration."],
     "christmas tips", minutes=(10, 14.5), voice="en_US-lessac-high")
